identity or format evidence found in reviewed exact-edition and content sources."}],"work_id":1127,"language":"nl","bound_author_id":671,"text":"Sasja voelt zich thuis niet meer op haar gemak sinds de vriend van haar moeder en diens zoon bij hen wonen. Ze durft nauwelijks uit te leggen wat er misgaat. Ook Ruben bewaart iets wat hij niet met iedereen wil delen. Wanneer zijn vriend Jorrit achter dat geheim komt, raken vertrouwen en vriendschap beschadigd. De jongeren moeten beslissen wanneer zwijgen bescherming biedt en wanneer juist hulp nodig is.","source_type":"official_publisher","source_name":"www.carryslee.nl","source_url":"https://www.carryslee.nl/boek/1907/carry-slee-paniek.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789048849161","key":{"isbn_13":"9789048849161"},"before":null,"after":{"work_id":1128,"title":"Lover of Loser","isbn_13":"9789048849161","isbn_10":"9048849160","language":"nld","publisher":"Overamstel Uitgevers","open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789048849161","key":{"edition_id":"@edition:9789048849161"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://www.carryslee.nl/boek/774/carry-slee-lover-of-loser.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/132920/lover-of-loser.html","checkedAt":"2026-10-31T20:32:29.004Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"8753e08488c843a443fe3e52a1ef96b646febeed9ea2bce2dc8d6e0875e8bbc9"},{"url":"https://metadata.isbn.nl/ie_fcache/0000542979_Lover_of_Loser_0_0.jpg","checkedAt":"2026-10-31T20:34:04.377Z","http":200,"sha256":"2aef7387737271230e94c4a2c762ed3590d19ab93eb276fdefcda091d5ed410f","bytes":744764,"fact":"Full source image decoded an