ates1May/8May conflict is retained, no edition-date database field is invented."}],"work_id":1128,"language":"nl","bound_author_id":671,"text":"Eva heeft moeite met haar stiefvader, maar vindt weinig gehoor bij haar moeder. Ook haar beste vriendin lijkt nauwelijks tijd te hebben. Terwijl Eva twijfelt of ze haar gevoelens met Mees kan delen, wordt aandacht van iemand anders verleidelijk. Het boek laat de lezer op twee momenten kiezen hoe het verhaal verdergaat en onderzoekt hoe kwetsbaarheid, vertrouwen en beïnvloeding samen kunnen komen.","source_type":"official_publisher","source_name":"www.carryslee.nl","source_url":"https://www.carryslee.nl/boek/774/carry-slee-lover-of-loser.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789025852511","key":{"id":1131},"before":{"id":1131,"title":"De griezelbus","isbn_10":null,"isbn_13":"9789025852511","work_id":1131,"language":null,"publisher":"Leopold","created_at":"2026-09-03T19:11:00.96069+00:00","open_library_edition_id":"OL35615775M"},"after":{"id":1131,"title":"De Griezelbus 7","isbn_10":null,"isbn_13":"9789025852511","work_id":1131,"language":"nld","publisher":"Leopold","created_at":"2026-09-03T19:11:00.96069+00:00","open_library_edition_id":"OL35615775M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025852511","key":{"edition_id":1131},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://www.bibliotheek.nl/catalogus/titel.322278295.html/de-griezelbus/","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1414145/de-griezelbus.html","checkedAt":"2026-10-31T20:12:00.028Z","fact":"Exact ISBN/title/format/publisher/cover binding; language requires exact-edition evidence","sha256":"bea99f885356b0d3a6fdbda5d68e99fbe5d87f341e1805a9fce51cc01fda678f"},{"url":"https://metadata.is