c9729f","bytes":80853,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"No conflicting identity or format evidence found in reviewed exact-edition and content sources."}],"work_id":1148,"language":"nl","bound_author_id":677,"text":"Vijftig jaar na John Steinbecks reis door de Verenigde Staten volgt Geert Mak diens route opnieuw. Onderweg onderzoekt hij hoe het land en de verwachtingen van zijn inwoners zijn veranderd. Historische gebeurtenissen krijgen betekenis naast ontmoetingen en waarnemingen tijdens de reis. Zo vergelijkt hij het Amerikaanse zelfbeeld met het dagelijkse leven en vraagt hij wat Amerika en Europa nog met elkaar verbindt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/69197/reizen-zonder-john.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789045039770","key":{"id":1149},"before":{"id":1149,"title":"Grote verwachtingen","isbn_10":null,"isbn_13":"9789045039770","work_id":1149,"language":null,"publisher":"Atlas Contact","created_at":"2026-09-03T19:11:47.042594+00:00","open_library_edition_id":"OL32616421M"},"after":{"id":1149,"title":"Grote verwachtingen","isbn_10":null,"isbn_13":"9789045039770","work_id":1149,"language":"nld","publisher":"Atlas Contact","created_at":"2026-09-03T19:11:47.042594+00:00","open_library_edition_id":"OL32616421M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789045039770","key":{"edition_id":1149},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://metadata.isbn.nl/1183197/grote-verwachtingen.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"},{"url":"https://metadata.isbn.nl/1183197/grote-verwachtingen.html","checkedAt