9d33a0b9359d806f790b58d956e58f5259432cd5d94f6296026e82e5eb5779bd","bytes":366237,"fact":"Full source image decoded and inspected: matching title/author and exact edition source. Language established bibliographically, never from jacket alone."},{"reviewNote":"No conflicting identity or format evidence found in reviewed exact-edition and content sources."}],"work_id":1160,"language":"nl","bound_author_id":679,"text":"Allene Tew groeit op buiten de Amerikaanse elite, maar raakt gedurende haar leven verbonden met vermogende families en Europese adel. Haar geschiedenis voert langs grote voorspoed, persoonlijk verlies en nieuwe huwelijken. Annejet van der Zijl reconstrueert hoe Tew telkens een ander bestaan opbouwt. Tegen de achtergrond van maatschappelijke omwentelingen volgt het boek een vrouw wier levensloop Amerika en Europa met elkaar verbindt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/264071/de-amerikaanse-prinses.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789045021829","key":{"id":1164},"before":{"id":1164,"title":"Hemelvaart","isbn_10":null,"isbn_13":"9789045021829","work_id":1164,"language":null,"publisher":"Uitgeverij Atlas Contact","created_at":"2026-09-03T19:12:19.965366+00:00","open_library_edition_id":"OL30967956M"},"after":{"id":1164,"title":"Hemelvaart","isbn_10":null,"isbn_13":"9789045021829","work_id":1164,"language":"nld","publisher":"Uitgeverij Atlas Contact","created_at":"2026-09-03T19:12:19.965366+00:00","open_library_edition_id":"OL30967956M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789045021829","key":{"edition_id":1164},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-10-31T20:50:00Z","review_batch":"nl-followup-004-20261031","evidence":[{"url":"https://metadata.isbn.nl/162087/hemelvaart.html","checkedAt":"2026-10-31","fact":"Reviewed content for original Dutch summary; not a copied publisher blurb"}